"""Turns the fonts in assets/fonts into src/app/fonts_data.cpp, so that they travel inside the executable.

Run it from the project's root when the fonts change. Only the standard library is needed.
"""
FONTS = [('kRegular', 'Ubuntu-R.ttf'), ('kMedium', 'Ubuntu-M.ttf'), ('kMono', 'UbuntuMono-R.ttf')]

lines = [
    '// Generated by tools/embed_fonts.py from assets/fonts. Do not edit.',
    '#include "app/fonts_data.hpp"',
    '',
    'namespace bancada::app::fonts {',
    '',
]
for name, file_name in FONTS:
    data = open('assets/fonts/' + file_name, 'rb').read()
    lines.append(f'const std::uint8_t {name}[] = {{')
    for start in range(0, len(data), 40):
        lines.append(','.join(str(byte) for byte in data[start:start + 40]) + ',')
    lines.append('};')
    lines.append(f'const std::size_t {name}Size = {len(data)};')
    lines.append('')
lines.append('}  // namespace bancada::app::fonts')
lines.append('')
open('src/app/fonts_data.cpp', 'w', newline='\n').write('\n'.join(lines))
print('ok')
